awaitable<void> activator(Channel& in, Channel& out, Service& svc) {
  for (;;) {
    Message m = co_await in.receive();
    try {
      if (auto r = co_await svc.handle(decode<Order>(m.payload)))
        co_await out.send(encode(*r));
    } catch (const std::exception& e) { co_await errors.send(describe(e)); }
  }
}
